// ── WatchProviderCard ──────────────────────────────────────────────────────────

function WatchProviderCard({ provider, title, appleTVUrl }: { provider: WatchProvider; title: string; appleTVUrl: string | null }) {
  const bg  = PROVIDER_COLORS[provider.provider_name] ?? theme.colors.surface;
  const url = getWatchUrl(provider, title, appleTVUrl);

  return (
    <ProviderCard bg={bg} href={url} target="_blank" rel="noreferrer">
      {provider.logo_path && (
        <ProviderLogo src={logoUrl(provider.logo_path)} alt={provider.provider_name} />
      )}
      <ProviderInfo>
        <ProviderName>{provider.provider_name}</ProviderName>
        <OpenLabel>
          <ExternalLink size={9} />
          {opensViaAppleTV(provider.provider_id) ? 'Open in Apple TV' : `Open in ${provider.provider_name}`}
        </OpenLabel>
      </ProviderInfo>
    </ProviderCard>
  );
}

// ── Main component ─────────────────────────────────────────────────────────────

interface Props {
  item: MediaItem;
  apiKey: string;
  onBack: () => void;
  onLibraryChange?: () => void;
  onSelect?: (item: MediaItem) => void;
}

export function DetailPage({ item, apiKey, onBack, onLibraryChange, onSelect }: Props) {
  const [detail,    setDetail]    = useState<MediaDetail | null>(null);
  const [videos,    setVideos]    = useState<VideoResult[]>([]);
  const [providers, setProviders] = useState<WatchProviders | null>(null);
  const [cast,      setCast]      = useState<CastMember[]>([]);
  const [recommended, setRecommended] = useState<MediaItem[]>([]);
  const [loading,   setLoading]   = useState(true);
  const [appleTVUrl,  setAppleTVUrl]  = useState<string | null>(null);
  const [trailerActive, setTrailerActive] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const [fav,  setFav]  = useState(() => isFavorite(item));
  const [seen, setSeen] = useState(() => isSeen(item));

  const title = mediaTitle(item);
  const year  = mediaYear(item);

  // Keyboard dismiss — close trailer first, then back
  useEffect(() => {
    const h = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (trailerActive) { setTrailerActive(false); }
        else { onBack(); }
      }
    };
    document.addEventListener('keydown', h);
    return () => document.removeEventListener('keydown', h);
  }, [onBack, trailerActive]);

  // Scroll to top + reset on item change
  useEffect(() => {
    scrollRef.current?.scrollTo({ top: 0, behavior: 'instant' as ScrollBehavior });
  }, [item.id]);

  // Data fetch
  useEffect(() => {
    setLoading(true);
    setTrailerActive(false);
    Promise.all([
      getDetail(apiKey, item.media_type, item.id),
      getVideos(apiKey, item.media_type, item.id),
      getWatchProviders(apiKey, item.media_type, item.id),
      getCredits(apiKey, item.media_type, item.id),
      getRecommendations(apiKey, item.media_type, item.id),
    ]).then(([d, v, p, c, r]) => {
      setDetail(d);
      setVideos(v);
      setProviders(p);
      setCast(c);
      setRecommended(r);
      setLoading(false);
    }).catch(() => setLoading(false));

    fetchAppleTVUrl(title, item.media_type, year).then(setAppleTVUrl);
  }, [item.id, item.media_type, apiKey, title, year]);

  const trailer =
    videos.find((v) => v.site === 'YouTube' && (v.type === 'Trailer' || v.type === 'Teaser') && v.official)
    ?? videos.find((v) => v.site === 'YouTube' && v.type === 'Trailer')
    ?? videos.find((v) => v.site === 'YouTube');

  const handleFav  = useCallback(() => { toggleFavorite(item); setFav((f) => !f); onLibraryChange?.(); }, [item, onLibraryChange]);
  const handleSeen = useCallback(() => { toggleSeen(item);     setSeen((s) => !s); onLibraryChange?.(); }, [item, onLibraryChange]);

  const allFlatrate = [...(providers?.flatrate ?? [])].filter(
    (p, i, arr) => arr.findIndex((x) => x.provider_id === p.provider_id) === i,
  );
  const rentOnly = (providers?.rent ?? []).filter(
    (p) => !allFlatrate.find((f) => f.provider_id === p.provider_id),
  );

  // Primary watch URL (first flatrate provider or Apple TV fallback)
  const primaryProvider = allFlatrate[0];
  const primaryWatchUrl = primaryProvider
    ? getWatchUrl(primaryProvider, title, appleTVUrl)
    : appleTVUrl ?? `https://tv.apple.com/search?term=${encodeURIComponent(title)}`;

  const backdropSrc = backdropUrl(item.backdrop_path ?? detail?.backdrop_path ?? null, 'w1280');

  return (
    <Overlay ref={scrollRef}>
      {loading && (
        <LoadingOverlay>
          <LoadingSpinner />
        </LoadingOverlay>
      )}
      <PageInner>
        {/* ── Hero ── */}
        <HeroWrap src={backdropSrc}>
          <HeroContent>
            <HeroTitle>{title}</HeroTitle>
            {detail?.tagline && <HeroTagline>"{detail.tagline}"</HeroTagline>}

            <HeroMeta>
              <RatingBadge>
                <Star size={15} fill="currentColor" />
                {item.vote_average.toFixed(1)}
              </RatingBadge>
              {year && <MetaItem><Calendar size={13} />{year}</MetaItem>}
              {detail?.runtime && (
                <MetaItem>
                  <Clock size={13} />
                  {Math.floor(detail.runtime / 60)}h {detail.runtime % 60}m
                </MetaItem>
              )}
              {detail?.number_of_seasons && (
                <MetaItem>
                  <Tv size={13} />
                  {detail.number_of_seasons} season{detail.number_of_seasons !== 1 ? 's' : ''}
                </MetaItem>
              )}
            </HeroMeta>

            {detail?.genres && detail.genres.length > 0 && (
              <HeroGenres>
                {detail.genres.map((g) => <GenreChip key={g.id}>{g.name}</GenreChip>)}
              </HeroGenres>
            )}

            <CTARow>
              <WatchNowBtn href={primaryWatchUrl} target="_blank" rel="noreferrer">
                <Play size={16} fill="black" />
                Watch Now
              </WatchNowBtn>

              {trailer && (
                <TrailerBtn onClick={() => setTrailerActive(true)}>
                  <Clapperboard size={15} />
                  Trailer
                </TrailerBtn>
              )}

              <ActionBtn active={fav} onClick={handleFav}>
                <Heart size={14} fill={fav ? 'currentColor' : 'none'} />
                {fav ? 'Favorited' : 'Favorite'}
              </ActionBtn>

              <ActionBtn active={seen} onClick={handleSeen}>
                {seen ? <EyeOff size={14} /> : <Eye size={14} />}
                {seen ? 'Unseen' : 'Mark Seen'}
              </ActionBtn>

              {(fav || seen) && (
                <ActionBtn danger onClick={() => {
                  if (fav) { toggleFavorite(item); setFav(false); }
                  if (seen) { toggleSeen(item); setSeen(false); }
                  onLibraryChange?.();
                }}>
                  <Trash2 size={14} />
                </ActionBtn>
              )}
            </CTARow>
          </HeroContent>
        </HeroWrap>

        {/* ── Body ── */}
        <Body>
          {/* Overview */}
          {loading
            ? <LoadingText>Loading…</LoadingText>
            : <Overview>{item.overview}</Overview>
          }

          {/* Trailer Modal */}
          {trailer && trailerActive && (
            <TrailerBackdrop onClick={(e) => { if (e.target === e.currentTarget) setTrailerActive(false); }}>
              <TrailerContainer>
                <TrailerClose onClick={() => setTrailerActive(false)}>
                  <X size={14} /> Close
                </TrailerClose>
                <TrailerIframe>
                  <iframe
                    src={`https://www.youtube.com/embed/${trailer.key}?autoplay=1&rel=0&modestbranding=1`}
                    title={trailer.name}
                    allowFullScreen
                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                  />
                </TrailerIframe>
              </TrailerContainer>
            </TrailerBackdrop>
          )}

          {/* Cast */}
          {(loading || cast.length > 0) && (
            <Section>
              <SectionHeader>
                <SectionIcon><Users size={15} /></SectionIcon>
                <SectionTitle>Cast</SectionTitle>
              </SectionHeader>
              {loading ? <LoadingText>Loading cast…</LoadingText> : (
                <CastScroll>
                  {cast.map((member) => (
                    <CastCard key={member.id}>
                      {member.profile_path
                        ? <CastPhoto src={profileUrl(member.profile_path, 'w185')} alt={member.name} loading="lazy" />
                        : <CastPhotoPlaceholder>👤</CastPhotoPlaceholder>
                      }
                      <CastInfo>
                        <CastName>{member.name}</CastName>
                        {member.character && <CastCharacter>{member.character}</CastCharacter>}
                      </CastInfo>
                    </CastCard>
                  ))}
                </CastScroll>
              )}
            </Section>
          )}

          {/* Where to Watch */}
          <Section>
            <SectionHeader>
              <SectionIcon><MonitorPlay size={15} /></SectionIcon>
              <SectionTitle>Where to Watch</SectionTitle>
            </SectionHeader>

            {loading ? <LoadingText>Loading streaming info…</LoadingText>
              : allFlatrate.length > 0 ? (
                <>
                  <StreamGrid>
                    {allFlatrate.map((p) => (
                      <WatchProviderCard key={p.provider_id} provider={p} title={title} appleTVUrl={appleTVUrl} />
                    ))}
                  </StreamGrid>
                  {rentOnly.length > 0 && (
                    <div style={{ marginTop: 8 }}>
                      <InfoLabel>Also available to rent</InfoLabel>
                      <StreamGrid>
                        {rentOnly.map((p) => (
                          <InfoBadge key={p.provider_id} bg={PROVIDER_COLORS[p.provider_name] ?? theme.colors.surface}>
                            {p.logo_path && <SmallLogo src={logoUrl(p.logo_path)} alt={p.provider_name} />}
                            <ProviderName style={{ color: '#fff' }}>{p.provider_name}</ProviderName>
                          </InfoBadge>
                        ))}
                      </StreamGrid>
                    </div>
                  )}
                </>
              ) : (providers?.rent ?? []).length > 0 ? (
                <div>
                  <NoStream>Not on any streaming subscription right now.</NoStream>
                  <InfoLabel style={{ marginTop: 12 }}>Available to rent</InfoLabel>
                  <StreamGrid>
                    {(providers?.rent ?? []).map((p) => (
                      <InfoBadge key={p.provider_id} bg={PROVIDER_COLORS[p.provider_name] ?? theme.colors.surface}>
                        {p.logo_path && <SmallLogo src={logoUrl(p.logo_path)} alt={p.provider_name} />}
                        <ProviderName style={{ color: '#fff' }}>{p.provider_name}</ProviderName>
                      </InfoBadge>
                    ))}
                  </StreamGrid>
                </div>
              ) : (
                <NoStream>No streaming info available for your region (US).</NoStream>
              )
            }
          </Section>

          {/* You Might Also Like */}
          {recommended.length > 0 && (
            <Section>
              <SectionHeader>
                <SectionIcon><Star size={15} /></SectionIcon>
                <SectionTitle>You Might Also Like</SectionTitle>
              </SectionHeader>
              <CastScroll>
                {recommended.map((rec) => (
                  <RecCard key={rec.id} onClick={() => onSelect?.(rec)}>
                    {posterUrl(rec.poster_path) ? (
                      <RecPoster src={posterUrl(rec.poster_path, 'w185')} alt={mediaTitle(rec)} loading="lazy" />
                    ) : (
                      <RecPosterEmpty>🎬</RecPosterEmpty>
                    )}
                    <CastInfo>
                      <CastName>{mediaTitle(rec)}</CastName>
                      <CastCharacter>
                        <Star size={9} fill="#e3b341" color="#e3b341" style={{ verticalAlign: -1 }} /> {rec.vote_average.toFixed(1)} · {mediaYear(rec)}
                      </CastCharacter>
                    </CastInfo>
                  </RecCard>
                ))}
              </CastScroll>
            </Section>
          )}
        </Body>
      </PageInner>
    </Overlay>
  );
}
