import React, { useRef, useState } from 'react';
import styled from '@emotion/styled';
import { theme } from '@atlantis/shared';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { MediaCard } from './MediaCard';
import type { MediaItem } from '../tmdb';

const RowWrap = styled.div`
  display: flex;
  flex-direction: column;
  gap: ${theme.spacing.md};
  padding: 0 ${theme.spacing.xxl};
  position: relative;
`;

const RowHeader = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
`;

const RowTitle = styled.h2`
  font-size: 18px;
  font-weight: 700;
  color: ${theme.colors.mainText};
  margin: 0;
  letter-spacing: -0.01em;
`;

const ScrollBtns = styled.div`
  display: flex;
  gap: ${theme.spacing.sm};
`;

const ScrollBtn = styled.button`
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: 1px solid ${theme.colors.border};
  background: ${theme.colors.surface};
  color: ${theme.colors.mainText};
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;

  &:hover {
    background: ${theme.colors.sidebarHover};
    border-color: ${theme.colors.accent};
    color: ${theme.colors.accent};
  }

  &:disabled {
    opacity: 0.3;
    cursor: not-allowed;
  }
`;

const TrackOuter = styled.div`
  position: relative;
  overflow: hidden;
`;

const Track = styled.div`
  display: flex;
  gap: ${theme.spacing.md};
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding-bottom: 4px;

  &::-webkit-scrollbar { display: none; }
`;

const EmptyRow = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  height: 240px;
  color: ${theme.colors.mainTextMuted};
  font-size: 14px;
  border: 1px dashed ${theme.colors.border};
  border-radius: ${theme.borderRadius.lg};
`;

const SkeletonCard = styled.div`
  width: 160px;
  aspect-ratio: 2/3;
  flex-shrink: 0;
  border-radius: 10px;
  background: linear-gradient(
    90deg,
    ${theme.colors.surface} 25%,
    ${theme.colors.sidebarHover} 50%,
    ${theme.colors.surface} 75%
  );
  background-size: 200% 100%;
  animation: shimmer 1.4s infinite;

  @keyframes shimmer {
    0% { background-position: 200% 0; }
    100% { background-position: -200% 0; }
  }
`;

interface Props {
  title: string;
  items: MediaItem[];
  loading?: boolean;
  onSelect: (item: MediaItem) => void;
}

const SCROLL_AMOUNT = 600;

export function ContentRow({ title, items, loading, onSelect }: Props) {
  const trackRef = useRef<HTMLDivElement>(null);
  const [canLeft, setCanLeft] = useState(false);
  const [canRight, setCanRight] = useState(true);

  const updateButtons = () => {
    const el = trackRef.current;
    if (!el) return;
    setCanLeft(el.scrollLeft > 0);
    setCanRight(el.scrollLeft + el.clientWidth < el.scrollWidth - 4);
  };

  const scrollLeft = () => {
    trackRef.current?.scrollBy({ left: -SCROLL_AMOUNT, behavior: 'smooth' });
    setTimeout(updateButtons, 350);
  };

  const scrollRight = () => {
    trackRef.current?.scrollBy({ left: SCROLL_AMOUNT, behavior: 'smooth' });
    setTimeout(updateButtons, 350);
  };

  return (
    <RowWrap>
      <RowHeader>
        <RowTitle>{title}</RowTitle>
        <ScrollBtns>
          <ScrollBtn onClick={scrollLeft} disabled={!canLeft}>
            <ChevronLeft size={16} />
          </ScrollBtn>
          <ScrollBtn onClick={scrollRight} disabled={!canRight || items.length === 0}>
            <ChevronRight size={16} />
          </ScrollBtn>
        </ScrollBtns>
      </RowHeader>

      <TrackOuter>
        {loading ? (
          <Track>
            {Array.from({ length: 10 }).map((_, i) => (
              <SkeletonCard key={i} />
            ))}
          </Track>
        ) : items.length === 0 ? (
          <EmptyRow>No results found</EmptyRow>
        ) : (
          <Track ref={trackRef} onScroll={updateButtons}>
            {items.map((item) => (
              <MediaCard key={`${item.media_type}-${item.id}`} item={item} onClick={onSelect} />
            ))}
          </Track>
        )}
      </TrackOuter>
    </RowWrap>
  );
}
